/**
 * EXPLODE - Itens
 *
 * Contrato de entrada:
 * {
 *   codigo_orcamento: string,
 *   orcamento_sharepoint_id: number,
 *   drive_file_id: string,
 *   orcamento: object,
 *   itens: array
 * }
 *
 * Contrato de saída:
 * Um item n8n por item do orçamento, contendo:
 * - contexto do orçamento;
 * - dados completos do item;
 * - array de tributos normalizado;
 * - vínculo pairedItem com a entrada.
 */

const entradas = $input.all();

if (entradas.length !== 1) {
  throw new Error(
    `EXPLODE - Itens esperava exatamente 1 orçamento por execução, mas recebeu ${entradas.length}.`
  );
}

const entrada = entradas[0]?.json ?? {};

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

function texto(valor) {
  return String(valor ?? '').trim();
}

function numero(valor, padrao = null) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return padrao;
  }

  if (typeof valor === 'number') {
    return Number.isFinite(valor)
      ? valor
      : padrao;
  }

  let normalizado = String(valor)
    .trim()
    .replace(/\s/g, '');

  /*
   * Formatos tratados:
   * 1.234,56 → 1234.56
   * 1234,56  → 1234.56
   * 1234.56  → 1234.56
   */
  if (
    normalizado.includes('.') &&
    normalizado.includes(',')
  ) {
    normalizado = normalizado
      .replace(/\./g, '')
      .replace(',', '.');
  } else if (normalizado.includes(',')) {
    normalizado = normalizado.replace(',', '.');
  }

  const convertido = Number(normalizado);

  return Number.isFinite(convertido)
    ? convertido
    : padrao;
}

function inteiroPositivo(valor, padrao) {
  const convertido = numero(valor, padrao);

  if (
    !Number.isFinite(convertido) ||
    convertido <= 0
  ) {
    return padrao;
  }

  return Math.trunc(convertido);
}

function booleanoOuNulo(valor) {
  if (valor === true || valor === false) {
    return valor;
  }

  if (typeof valor === 'string') {
    const normalizado = valor
      .trim()
      .toUpperCase();

    if (
      normalizado === 'TRUE' ||
      normalizado === 'SIM'
    ) {
      return true;
    }

    if (
      normalizado === 'FALSE' ||
      normalizado === 'NAO' ||
      normalizado === 'NÃO'
    ) {
      return false;
    }
  }

  return null;
}

function primeiroTexto(...valores) {
  for (const valor of valores) {
    const convertido = texto(valor);

    if (convertido) {
      return convertido;
    }
  }

  return '';
}

/* -------------------------------------------------------------------------- */
/* Contexto do orçamento                                                      */
/* -------------------------------------------------------------------------- */

const fieldsSharePoint =
  entrada.fields &&
  typeof entrada.fields === 'object' &&
  !Array.isArray(entrada.fields)
    ? entrada.fields
    : {};

const orcamentoEntrada =
  entrada.orcamento &&
  typeof entrada.orcamento === 'object' &&
  !Array.isArray(entrada.orcamento)
    ? entrada.orcamento
    : {};

const orcamento = {
  ...fieldsSharePoint,
  ...orcamentoEntrada
};

const itens =
  Array.isArray(entrada.itens)
    ? entrada.itens
    : Array.isArray(entrada.Itens)
      ? entrada.Itens
      : [];

const codigoOrcamento = primeiroTexto(
  entrada.Codigo_Orcamento,
  entrada.codigo_orcamento,
  fieldsSharePoint.Codigo_Orcamento,
  orcamento.codigo_orcamento,
  orcamento.Codigo_Orcamento
);

const numeroOrcamento = primeiroTexto(
  orcamento.numero_orcamento,
  orcamento.Numero_Orcamento,
  fieldsSharePoint.Numero_Orcamento,
  entrada.Numero_Orcamento
);

const driveFileId = primeiroTexto(
  entrada.drive_file_id,
  entrada.DriveFileId,
  entrada.driveFileId,
  fieldsSharePoint.DriveFileId,
  orcamento.drive_file_id,
  orcamento.DriveFileId,
  orcamento.driveFileId
);

const orcamentoSharePointId = inteiroPositivo(
  entrada._referencia_orcamento_validada === true ? entrada.orcamento_sharepoint_id : null,
  null
);
if (entrada._referencia_orcamento_validada !== true) {
  throw new Error('EXPLODE - Itens: referência do orçamento não foi validada no SharePoint.');
}
if (!codigoOrcamento) {
  throw new Error(
    'EXPLODE - Itens: Codigo_Orcamento não foi localizado no contrato de entrada.'
  );
}

if (!orcamentoSharePointId) {
  throw new Error(
    `EXPLODE - Itens: ID do orçamento no SharePoint não localizado para ${codigoOrcamento}.`
  );
}

if (itens.length === 0) {
  return [];
}

/* -------------------------------------------------------------------------- */
/* Normalização tributária                                                    */
/* -------------------------------------------------------------------------- */

function normalizarTributo(
  tipo,
  aliquota,
  valor,
  origem = 'CAMPO_PADRAO'
) {
  const tipoNormalizado = texto(tipo).toUpperCase();

  if (!tipoNormalizado) {
    return null;
  }

  const aliquotaNormalizada = numero(aliquota, 0);
  const valorNormalizado = numero(valor, 0);

  if (
    aliquotaNormalizada === 0 &&
    valorNormalizado === 0
  ) {
    return null;
  }

  return {
    tipo: tipoNormalizado,
    aliquota_percentual: aliquotaNormalizada,
    valor: valorNormalizado,
    origem
  };
}

function montarTributos(item) {
  const tributos = [];

  const tributosPadrao = [
    normalizarTributo(
      'IPI',
      item.ipi_percentual,
      item.ipi_valor
    ),
    normalizarTributo(
      'ICMS',
      item.icms_percentual,
      item.icms_valor
    ),
    normalizarTributo(
      'ICMS_ST',
      item.icms_st_percentual,
      item.icms_st_valor
    ),
    normalizarTributo(
      'PIS',
      item.pis_percentual,
      item.pis_valor
    ),
    normalizarTributo(
      'COFINS',
      item.cofins_percentual,
      item.cofins_valor
    ),
    normalizarTributo(
      'ISS',
      item.iss_percentual,
      item.iss_valor
    )
  ];

  for (const tributo of tributosPadrao) {
    if (tributo) {
      tributos.push(tributo);
    }
  }

  const outrosImpostos =
    Array.isArray(item.outros_impostos)
      ? item.outros_impostos
      : [];

  for (const imposto of outrosImpostos) {
    if (
      !imposto ||
      typeof imposto !== 'object' ||
      Array.isArray(imposto)
    ) {
      continue;
    }

    const tributo = normalizarTributo(
      imposto.tipo,
      imposto.aliquota_percentual,
      imposto.valor,
      'OUTROS_IMPOSTOS'
    );

    if (tributo) {
      tributos.push(tributo);
    }
  }

  /*
   * Compatibilidade com entradas antigas que já tragam
   * um array tributos pronto.
   */
  const tributosRecebidos =
    Array.isArray(item.tributos)
      ? item.tributos
      : [];

  for (const imposto of tributosRecebidos) {
    if (
      !imposto ||
      typeof imposto !== 'object' ||
      Array.isArray(imposto)
    ) {
      continue;
    }

    const tributo = normalizarTributo(
      imposto.tipo ??
      imposto.tipo_tributo,

      imposto.aliquota_percentual ??
      imposto.aliquota,

      imposto.valor ??
      imposto.valor_tributo,

      imposto.origem ?? 'ARRAY_TRIBUTOS'
    );

    if (!tributo) {
      continue;
    }

    /*
     * Evita duplicar o mesmo imposto caso ele exista
     * nos campos individuais e no array tributos.
     */
    const duplicado = tributos.some(
      existente =>
        existente.tipo === tributo.tipo &&
        existente.aliquota_percentual ===
          tributo.aliquota_percentual &&
        existente.valor === tributo.valor
    );

    if (!duplicado) {
      tributos.push(tributo);
    }
  }

  return tributos;
}

/* -------------------------------------------------------------------------- */
/* Explosão dos itens                                                         */
/* -------------------------------------------------------------------------- */

const numerosUtilizados = new Set();

return itens.map((itemRecebido, index) => {
  const item =
    itemRecebido &&
    typeof itemRecebido === 'object' &&
    !Array.isArray(itemRecebido)
      ? itemRecebido
      : {};

  const numeroItem = inteiroPositivo(
    item.numero_item,
    index + 1
  );

  if (numerosUtilizados.has(numeroItem)) {
    throw new Error(
      `EXPLODE - Itens: numero_item duplicado (${numeroItem}) no orçamento ${codigoOrcamento}.`
    );
  }

  numerosUtilizados.add(numeroItem);

  const numeroItemFormatado =
    String(numeroItem).padStart(3, '0');

  const codigoItem =
    `${codigoOrcamento}-ITEM-${numeroItemFormatado}`;

  const tributos = montarTributos(item);

  return {
    json: {
      /*
       * Preserva integralmente o item recebido.
       */
      ...item,

      numero_item: numeroItem,
      codigo_item: codigoItem,

      codigo_orcamento: codigoOrcamento,
      orcamento_sharepoint_id:
        orcamentoSharePointId,
      drive_file_id: driveFileId,

      fornecedor: primeiroTexto(
        orcamento.fornecedor,
        orcamento.Fornecedor
      ),

      numero_orcamento:
        numeroOrcamento,

      cnpj_fornecedor: primeiroTexto(
        orcamento.cnpj_fornecedor,
        orcamento.CNPJ_Fornecedor
      ),

      impostos_inclusos_preco:
        booleanoOuNulo(
          item.impostos_inclusos_preco
        ),

      tributos,

      metadados_item: {
        indice_origem: index,
        quantidade_tributos:
          tributos.length,
        origem:
          entrada.metadados_processamento
            ?.origem || 'DESCONHECIDA'
      }
    },

    pairedItem: {
      item: 0
    }
  };
});

const entrada = $json || {};

function texto(valor) {
  return String(valor ?? '').trim();
}

function numero(valor, padrao = null) {
  if (valor === null || valor === undefined || valor === '') return padrao;
  if (typeof valor === 'number') return Number.isFinite(valor) ? valor : padrao;
  let normalizado = String(valor).trim().replace(/R\$/gi, '').replace(/\s/g, '');
  if (normalizado.includes('.') && normalizado.includes(',')) {
    normalizado = normalizado.replace(/\./g, '').replace(',', '.');
  } else if (normalizado.includes(',')) {
    normalizado = normalizado.replace(',', '.');
  }
  const convertido = Number(normalizado);
  return Number.isFinite(convertido) ? convertido : padrao;
}

function inteiro(valor, padrao = null) {
  const convertido = numero(valor, padrao);
  return convertido === null ? padrao : Math.trunc(convertido);
}

function definido(valor) {
  return valor !== null && valor !== undefined && valor !== '';
}

const codigoItem = texto(entrada.codigo_item);
const codigoOrcamento = texto(entrada.codigo_orcamento);
const orcamentoSharePointId = inteiro(entrada.orcamento_sharepoint_id, null);

if (!codigoItem) throw new Error('codigo_item nao recebido no PREP - Itens.');
if (!codigoOrcamento) throw new Error(`codigo_orcamento nao recebido para ${codigoItem}.`);
if (!orcamentoSharePointId || orcamentoSharePointId < 1) {
  throw new Error(`orcamento_sharepoint_id invalido para ${codigoItem}.`);
}

const fieldsPatch = {
  Title: codigoItem,
  Codigo_Item: codigoItem,
  Codigo_OrcamentoLookupId: orcamentoSharePointId
};

const opcionais = {
  Numero_Item: inteiro(entrada.numero_item, null),
  DriveFileId: texto(entrada.drive_file_id),
  Fornecedor: texto(entrada.fornecedor),
  Codigo_Fornecedor: texto(entrada.codigo_produto_fornecedor ?? entrada.codigo_fornecedor),
  Referencia_Fornecedor: texto(entrada.referencia_fornecedor),
  Descricao_Original: texto(entrada.descricao_original),
  Quantidade: numero(entrada.quantidade, null),
  Unidade_Original: texto(entrada.unidade_original),
  Preco_Unitario: numero(entrada.preco_unitario, null),
  Preco_Total: numero(entrada.preco_total, null),
  NCM: texto(entrada.ncm),
  Material_Sugerido: texto(entrada.material_sugerido)
};

for (const [chave, valor] of Object.entries(opcionais)) {
  if (definido(valor)) fieldsPatch[chave] = valor;
}

// Campos de revisao humana nunca entram no PATCH automatico.
const fieldsPost = {
  ...fieldsPatch,
  Status_Revisao: 'PENDENTE',
  Enviado_Historico: 'NAO'
};

if (texto(entrada.observacao_item)) {
  fieldsPost.Observacao_Item = texto(entrada.observacao_item);
}

return {
  json: {
    ...entrada,
    codigo_item: codigoItem,
    codigo_orcamento: codigoOrcamento,
    orcamento_sharepoint_id: orcamentoSharePointId,
    drive_file_id: texto(entrada.drive_file_id),
    numero_item: inteiro(entrada.numero_item, null),
    tributos: Array.isArray(entrada.tributos) ? entrada.tributos : [],
    fields: fieldsPatch,
    fields_post: fieldsPost,
    fields_patch: fieldsPatch
  }
};

const preparado = $('PREP - Itens').item.json || {};
const registros = Array.isArray($json?.value) ? $json.value : [];
const exatos = registros.filter((registro) =>
  String(registro?.fields?.Codigo_Item ?? '').trim() === preparado.codigo_item
);

if (exatos.length > 1) {
  throw new Error(`COLISAO_CODIGO_ITEM: ${preparado.codigo_item} retornou ${exatos.length} registros.`);
}

const id = exatos[0]?.id ? Number(exatos[0].id) : null;
const existe = Number.isInteger(id) && id > 0;

return { json: { ...preparado, item_existe: existe, item_sharepoint_id: existe ? id : null, acao_item: existe ? 'PATCH' : 'POST' } };

const decisao = $('CODE - Decidir Item').item.json;

// No PATCH, o ID já veio do LOOKUP
const itemSharePointId = Number(
  decisao.item_sharepoint_id || 0
);

if (!itemSharePointId) {
  throw new Error(
    `ID do item não encontrado no PATCH: ${decisao.codigo_item}`
  );
}

return [
  {
    json: {
      operacao_item: 'PATCH',

      item_sharepoint_id: itemSharePointId,

      codigo_item:
        decisao.codigo_item,

      codigo_orcamento:
        decisao.codigo_orcamento,

      orcamento_sharepoint_id:
        Number(decisao.orcamento_sharepoint_id),

      drive_file_id:
        decisao.drive_file_id || '',

      tributos:
        Array.isArray(decisao.tributos)
          ? decisao.tributos
          : []
    }
  }
];

const decisao = $('CODE - Decidir Item').item.json;
const respostaGraph = $json || {};

// No POST, o Graph retorna o ID criado
const itemSharePointId = Number(
  respostaGraph.id || 0
);

if (!itemSharePointId) {
  throw new Error(
    `ID do item não retornado no POST: ${decisao.codigo_item}`
  );
}

return [
  {
    json: {
      operacao_item: 'POST',

      item_sharepoint_id: itemSharePointId,

      codigo_item:
        decisao.codigo_item,

      codigo_orcamento:
        decisao.codigo_orcamento,

      orcamento_sharepoint_id:
        Number(decisao.orcamento_sharepoint_id),

      drive_file_id:
        decisao.drive_file_id || '',

      tributos:
        Array.isArray(decisao.tributos)
          ? decisao.tributos
          : []
    }
  }
];

const entrada = $input.first().json;

return [
  {
    json: {
      ...entrada,
      entrada_original: entrada
    }
  }
];

const item = $json;

const tributos = Array.isArray(item.tributos)
  ? item.tributos
  : [];

if (tributos.length === 0) {
  return [
    {
      json: {
        possui_tributo: false,

        codigo_item: item.codigo_item,
        item_sharepoint_id: Number(item.item_sharepoint_id),

        codigo_orcamento: item.codigo_orcamento,
        orcamento_sharepoint_id:
          Number(item.orcamento_sharepoint_id),

        drive_file_id: item.drive_file_id || ''
      }
    }
  ];
}

return tributos.map((tributo, indice) => {
  const tipo = String(
    tributo.tipo ||
    tributo.tipo_tributo ||
    'OUTRO'
  )
    .trim()
    .toUpperCase();

  return {
    json: {
      possui_tributo: true,

      codigo_tributo_item:
        `${item.codigo_item}-${tipo}`,

      codigo_item:
        item.codigo_item,

      item_sharepoint_id:
        Number(item.item_sharepoint_id),

      codigo_orcamento:
        item.codigo_orcamento,

      orcamento_sharepoint_id:
        Number(item.orcamento_sharepoint_id),

      drive_file_id:
        item.drive_file_id || '',

      tipo_tributo:
        tipo,

      aliquota_percentual:
        tributo.percentual ??
        tributo.aliquota_percentual ??
        null,

      valor_tributo:
        tributo.valor ??
        tributo.valor_tributo ??
        null,

      situacao_tributaria:
        tributo.situacao_tributaria ||
        'NAO_INFORMADO',

      base_calculo:
        tributo.base_calculo ??
        '',

      iniciar_loop_tributos: true,

      observacao_fiscal:
        tributo.observacao_fiscal ||
        '',

      indice_tributo:
        indice + 1
    }
  };
});

const entrada = $json || {};
const texto = (valor) => String(valor ?? '').trim();
const numero = (valor) => {
  if (valor === null || valor === undefined || valor === '') return null;
  const normalizado = typeof valor === 'string' ? valor.trim().replace(/\s/g, '').replace(',', '.') : valor;
  const convertido = Number(normalizado);
  return Number.isFinite(convertido) ? convertido : null;
};

const codigoTributo = texto(entrada.codigo_tributo_item);
const itemId = Number(entrada.item_sharepoint_id);
const orcamentoId = Number(entrada.orcamento_sharepoint_id);
if (!codigoTributo) throw new Error('codigo_tributo_item ausente.');
if (!Number.isInteger(itemId) || itemId < 1) throw new Error(`item_sharepoint_id invalido para ${codigoTributo}.`);
if (!Number.isInteger(orcamentoId) || orcamentoId < 1) throw new Error(`orcamento_sharepoint_id invalido para ${codigoTributo}.`);

const tipos = ['PIS', 'COFINS', 'ICMS', 'DIFAL', 'IPI', 'ISS', 'OUTRO', 'ICMS-ST'];
const situacoes = ['INCLUSO', 'A_INCLUIR', 'NAO_INFORMADO', 'NAO_APLICA', 'ISENTO'];
const tipoRecebido = texto(entrada.tipo_tributo || 'OUTRO').toUpperCase();
const situacaoRecebida = texto(entrada.situacao_tributaria || 'NAO_INFORMADO').toUpperCase();

const fieldsPatch = {
  Title: codigoTributo,
  Codigo_Tributo_Item: codigoTributo,
  Codigo_ItemLookupId: itemId,
  Codigo_OrcamentoLookupId: orcamentoId,
  Tipo_Tributo: tipos.includes(tipoRecebido) ? tipoRecebido : 'OUTRO',
  Situacao_Tributaria: situacoes.includes(situacaoRecebida) ? situacaoRecebida : 'NAO_INFORMADO'
};

const opcionais = {
  DriveFileId: texto(entrada.drive_file_id),
  Aliquota_Percentual: numero(entrada.aliquota_percentual),
  Valor_Tributo: numero(entrada.valor_tributo),
  Base_Calculo: numero(entrada.base_calculo),
  Observacao_Fiscal: texto(entrada.observacao_fiscal)
};
for (const [chave, valor] of Object.entries(opcionais)) {
  if (valor !== null && valor !== '') fieldsPatch[chave] = valor;
}

return [{ json: { ...entrada, fields: fieldsPatch, fields_patch: fieldsPatch, fields_post: { ...fieldsPatch, Status_Revisao: 'PENDENTE' } } }];

const preparado = $('PREP - Tributo').item.json || {};
const registros = Array.isArray($json?.value) ? $json.value : [];
const exatos = registros.filter((registro) =>
  String(registro?.fields?.Codigo_Tributo_Item ?? '').trim() === preparado.codigo_tributo_item
);
if (exatos.length > 1) {
  throw new Error(`COLISAO_CODIGO_TRIBUTO: ${preparado.codigo_tributo_item} retornou ${exatos.length} registros.`);
}
const id = exatos[0]?.id ? Number(exatos[0].id) : null;
if (id !== null && (!Number.isInteger(id) || id < 1)) throw new Error('ID de tributo invalido retornado pelo SharePoint.');
return [{ json: { ...preparado, tributo_existe: Boolean(id), tributo_sharepoint_id: id } }];

const original = $('CODE - Decidir Tributo').item.json;

return [
  {
    json: {
      codigo_tributo_item:
        original.codigo_tributo_item,

      codigo_item:
        original.codigo_item,

      item_sharepoint_id:
        original.item_sharepoint_id,

      operacao_tributo:
        original.tributo_existe
          ? 'PATCH'
          : 'POST',

      tributo_processado: true
    }
  }
];

const original = $('CODE - Decidir Tributo').item.json;

return [
  {
    json: {
      codigo_tributo_item:
        original.codigo_tributo_item,

      codigo_item:
        original.codigo_item,

      item_sharepoint_id:
        original.item_sharepoint_id,

      operacao_tributo:
        original.tributo_existe
          ? 'PATCH'
          : 'POST',

      tributo_processado: true
    }
  }
];

const entrada = $json || {};

const descricaoOriginal =
  String(entrada.descricao_original ?? '').trim();

return {
  json: {
    ...entrada,
    descricao_original: descricaoOriginal
  }
};

/**
 * EXPLODE - Itens
 *
 * Contrato de entrada:
 * {
 *   codigo_orcamento: string,
 *   orcamento_sharepoint_id: number,
 *   drive_file_id: string,
 *   orcamento: object,
 *   itens: array
 * }
 *
 * Contrato de saída:
 * Um item n8n por item do orçamento, contendo:
 * - contexto do orçamento;
 * - dados completos do item;
 * - array de tributos normalizado;
 * - vínculo pairedItem com a entrada.
 */

const entradas = $input.all();

if (entradas.length !== 1) {
  throw new Error(
    `EXPLODE - Itens esperava exatamente 1 orçamento por execução, mas recebeu ${entradas.length}.`
  );
}

const entrada = entradas[0]?.json ?? {};

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

function texto(valor) {
  return String(valor ?? '').trim();
}

function numero(valor, padrao = null) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return padrao;
  }

  if (typeof valor === 'number') {
    return Number.isFinite(valor)
      ? valor
      : padrao;
  }

  let normalizado = String(valor)
    .trim()
    .replace(/\s/g, '');

  /*
   * Formatos tratados:
   * 1.234,56 → 1234.56
   * 1234,56  → 1234.56
   * 1234.56  → 1234.56
   */
  if (
    normalizado.includes('.') &&
    normalizado.includes(',')
  ) {
    normalizado = normalizado
      .replace(/\./g, '')
      .replace(',', '.');
  } else if (normalizado.includes(',')) {
    normalizado = normalizado.replace(',', '.');
  }

  const convertido = Number(normalizado);

  return Number.isFinite(convertido)
    ? convertido
    : padrao;
}

function inteiroPositivo(valor, padrao) {
  const convertido = numero(valor, padrao);

  if (
    !Number.isFinite(convertido) ||
    convertido <= 0
  ) {
    return padrao;
  }

  return Math.trunc(convertido);
}

function booleanoOuNulo(valor) {
  if (valor === true || valor === false) {
    return valor;
  }

  if (typeof valor === 'string') {
    const normalizado = valor
      .trim()
      .toUpperCase();

    if (
      normalizado === 'TRUE' ||
      normalizado === 'SIM'
    ) {
      return true;
    }

    if (
      normalizado === 'FALSE' ||
      normalizado === 'NAO' ||
      normalizado === 'NÃO'
    ) {
      return false;
    }
  }

  return null;
}

function primeiroTexto(...valores) {
  for (const valor of valores) {
    const convertido = texto(valor);

    if (convertido) {
